INSERT INTO `v1_0d733b39c1b4f200ecde636d692b961d65fd6243bd3e5ac7dc3edea76b5ec890` VALUES (6, 0, 11, "マコトさん？\nどうかしましたか？\n何やら不穏な気配を\n感じ取ったのですが", 0.8, 1, 6, 6011, 0, 129911, 0);
INSERT INTO `v1_0d733b39c1b4f200ecde636d692b961d65fd6243bd3e5ac7dc3edea76b5ec890` VALUES (6, "", 91, "", "", "", "", 6012, "", 0, "");
