INSERT INTO `v1_0d733b39c1b4f200ecde636d692b961d65fd6243bd3e5ac7dc3edea76b5ec890` VALUES (7, 0, 11, "私の班のみなさんも\n変わらず訓練に励んで\nいるようですわね\n殊勝なことです", 0.3, 1, 6, 7006, 0, 129911, 0);
INSERT INTO `v1_0d733b39c1b4f200ecde636d692b961d65fd6243bd3e5ac7dc3edea76b5ec890` VALUES (7, "", 91, "", "", "", "", 7007, "", 0, "");
